INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch02$PT134-S3-Q2$batch02$, 134, 3, 2, $batch02$Flaw$batch02$, $batch02$Principle: If you sell an item that you know to be defective, telling the buyer that the item is sound, you thereby commit fraud. Application: Wilton sold a used bicycle to Harris, knowing very little about its condition. Wilton told Harris that the bicycle was in good working condition, but Harris soon learned that the brakes were defective. Wilton was therefore guilty of fraud.$batch02$, $batch02$The application of the principle is most vulnerable to criticism on the grounds that$batch02$, $batch02$E$batch02$, true, $batch02$Batch 02 approved 2026-10-01; question text from local bank.$batch02$ FROM lr_sections s WHERE s.preptest=134 AND s.section=3 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q2$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$A$batch02$, $batch02$the application fails to establish whether Wilton was given the opportunity to repair the brakes$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q2$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$A$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$B$batch02$, $batch02$the application fails to indicate how much money Wilton received for the bicycle$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q2$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$B$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$C$batch02$, $batch02$the application uses the word “defective” in a sense that is crucially different from how it is used in the statement of the principle$batch02$, $batch02$Not Equivocation$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q2$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$C$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$D$batch02$, $batch02$Harris might not have believed Wilton’s statement about the bicycle’s condition$batch02$, $batch02$Out of Scope$batch02$, false FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q2$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$D$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch02$E$batch02$, $batch02$asserting something without justification is not the same as asserting something one knows to be false$batch02$, $batch02$Correct$batch02$, true FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q2$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch02$E$batch02$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch02$PT134-S3-Q2$batch02$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch02$Conclusion$batch02$, $batch02$Wilton committed fraud.$batch02$), (1, $batch02$Evidence$batch02$, $batch02$Principle: sell an item you *know* is defective + tell the buyer it is sound → fraud. Wilton knew very little about the bicycle, said it was in good condition, and the brakes turned out to be defective.$batch02$), (2, $batch02$Evaluate$batch02$, $batch02$Check each part of the trigger. Sold an item: yes. Told the buyer it was sound: yes. *Knew* it was defective: no. The stimulus says Wilton knew very little about its condition. He spoke carelessly, but the principle only covers sellers who know the item is bad. Without that piece, the rule never fires.$batch02$), (3, $batch02$Goal$batch02$, $batch02$Look for the missing knowledge condition.$batch02$)) v(position,label,body) WHERE q.qid=$batch02$PT134-S3-Q2$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch02$A$batch02$, $batch02$The principle says nothing about a chance to repair. Fraud under it depends on knowledge and the seller's statement.$batch02$), ($batch02$B$batch02$, $batch02$The price is irrelevant to whether the principle applies. An answer asking for a number is almost never the flaw.$batch02$), ($batch02$C$batch02$, $batch02$"Defective" means the same thing in both places: the item does not work properly. The brakes were defective in that sense.$batch02$), ($batch02$D$batch02$, $batch02$The principle does not require the buyer to believe the seller. Fraud is defined by what the seller knows and says.$batch02$), ($batch02$E$batch02$, $batch02$Wilton asserted the bicycle was sound without good reason to think so. That is not the same as asserting it while *knowing* it was defective, which is what the principle requires. The application treats careless assertion as knowing falsehood.$batch02$)) v(letter,body) WHERE q.qid=$batch02$PT134-S3-Q2$batch02$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
